import json
import re
import sys

deviceStatus = "helper-failure"
deviceStatusCode = "500"
deviceMessage = "Device inspection did not complete."
deviceResultJson = json.dumps({"error":deviceMessage}, separators=(",", ":"))
deviceRelationJson = ""

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def relationship_type_ok(value, expected):
    return isinstance(value, dict) and value.get("ObjectType") == expected and value.get("ClassId") in (None,"mo.MoRef",expected)

try:
    body = json.loads(sys.argv[1])
    deviceType = sys.argv[2]
    selector = sys.argv[3]
    organizationMoid = sys.argv[4]
    values = body.get("Results") if isinstance(body, dict) else None
    if not isinstance(values, list):
        raise ValueError("Device response is missing a Results array.")
    if len(values) == 0:
        deviceStatus = "invalid"
        deviceStatusCode = "404"
        deviceMessage = "No device matched the exact selector, route, and organization scope."
    elif len(values) > 1:
        deviceStatus = "invalid"
        deviceStatusCode = "409"
        deviceMessage = "Multiple devices matched the exact selector, route, and organization scope."
    else:
        item = values[0]
        problems = []
        if not isinstance(item, dict):
            raise ValueError("The device result is not an object.")
        moid = item.get("Moid")
        if not safe_moid(moid):
            problems.append("Device Moid is missing or not URL-safe.")
        permissions = item.get("PermissionResources")
        matches = [] if not isinstance(permissions, list) else [rel for rel in permissions if relationship_type_ok(rel,"organization.Organization") and rel.get("Moid") == organizationMoid]
        if len(matches) != 1:
            problems.append("Device PermissionResources must contain exactly one matching organization relationship.")
        relationMoid = moid
        relationType = ""
        targetType = item.get("TargetType")
        if deviceType == "Server":
            if item.get("ObjectType") != "compute.PhysicalSummary" or item.get("ClassId") not in (None,"compute.PhysicalSummary"):
                problems.append("Server result must be compute.PhysicalSummary.")
            if item.get("Name") != selector and item.get("Serial") != selector:
                problems.append("Server result Name or Serial does not exactly match the selector.")
            if item.get("SourceObjectType") not in ("compute.Blade","compute.RackUnit"):
                problems.append("Server SourceObjectType must be compute.Blade or compute.RackUnit.")
            else:
                relationType = item.get("SourceObjectType")
        elif deviceType == "Chassis":
            if item.get("ObjectType") != "equipment.Chassis" or item.get("ClassId") not in (None,"equipment.Chassis"):
                problems.append("Chassis result must be equipment.Chassis.")
            if item.get("Name") != selector and item.get("Serial") != selector:
                problems.append("Chassis result Name or Serial does not exactly match the selector.")
            relationType = "equipment.Chassis"
        else:
            if item.get("ObjectType") != "asset.Target" or item.get("ClassId") not in (None,"asset.Target") or item.get("Name") != selector:
                problems.append("Asset target result identity or discriminator is inconsistent.")
            if deviceType == "Fabric Interconnect" and targetType not in ("UCSFI","UCSFIISM"):
                problems.append("Fabric Interconnect target must use TargetType UCSFI or UCSFIISM.")
            elif deviceType == "Unified Edge or eCMC" and targetType != "UCSXECMC":
                problems.append("Unified Edge or eCMC target must use TargetType UCSXECMC.")
            elif deviceType == "Registered Target" and (not isinstance(targetType,str) or not targetType):
                problems.append("Registered Target must return a nonblank TargetType.")
            if deviceType == "Registered Target":
                registration = item.get("RegisteredDevice")
                if not relationship_type_ok(registration,"asset.DeviceRegistration") or not safe_moid(registration.get("Moid")):
                    problems.append("Registered Target must expose one valid asset.DeviceRegistration relationship.")
                else:
                    relationMoid = registration.get("Moid")
                    relationType = "asset.DeviceRegistration"
            else:
                relationType = "asset.Target"
        if problems:
            deviceStatus = "invalid"
            deviceStatusCode = "502"
            deviceMessage = " ".join(problems)
        else:
            relation = {"ClassId":"mo.MoRef","ObjectType":relationType,"Moid":relationMoid}
            deviceRelationJson = json.dumps(relation, separators=(",", ":"))
            deviceStatus = "ready"
            deviceStatusCode = "200"
            deviceMessage = "Exactly one device and its concrete relationship identity were validated."
    deviceResultJson = json.dumps({"status":deviceStatus,"message":deviceMessage,"deviceType":deviceType,"relationship":json.loads(deviceRelationJson) if deviceRelationJson else None,"mappingRequiresTenantValidation":deviceType in ("Server","Fabric Interconnect","Unified Edge or eCMC","Registered Target")}, separators=(",", ":"))
except Exception as exc:
    deviceStatus = "helper-failure"
    deviceStatusCode = "500"
    deviceMessage = str(exc)
    deviceResultJson = json.dumps({"error":"Device inspection failed","detail":deviceMessage}, separators=(",", ":"))
